  ('ookrotzn', 'ookrotzn', '', '', '', 'Tod und Sterben auf Wienerisch', 'abkratzen', '[{"kategorie": "wörtlich", "text": "\"abkratzen\" (vom mittelhochdeutschen \"abe kratzen\"=\"abkratzen\")"}, {"kategorie": "allg.", "text": "\"abkratzen\", \"abstreifen\", \"abtreten\""}, {"kategorie": "hist.", "text": "\"sich mit einem Kratzfuß verabschieden\" (der \"Kratzfuß\" war einst ein höfisches Anstandsritual: Dabei machte man mit dem linken Fuß eine rückwärtige Seitbewegung  und verbeugte sich untertänigst zum Abschied), \"den Kratzfuß machen\", \"einen tiefen Kratzfuß schlagen\""}, {"kategorie": "scherzhaft für", "text": "sterben, das Zeitliche segnen, [[maukas]] geen, [[ins]] Gras beißen, [[den]] Löffel abgeben, [[die]] Patschen strecken, [[die]] Eisen aufstellen"}]'::jsonb, 'Zwaa Schriad zruckdreedn, daunn ookrotzn und lautlos aussegee - so valossd ma in kaisalichn Audienzsoi!'),
  ('augschissana', 'Augschissana', 'der', '', '', 'Grundwortschatz Wienerisch', 'Angschissener', '[{"kategorie": "wörtlich", "text": "\"Angeschissener\" (vom mittelhochdeutschen \"schîӡen\"=\"scheißen\")"}, {"kategorie": "fig.", "text": "Scheißkerl, Flachwichser, Mistkerl, [[Arschloch]], [[Heini]], [[Dillo]], [[Schwindlicher]]"}, {"kategorie": "fig.", "text": "\"Hosenscheißer\" (\"jemand, der die Hosen voll hat\"), Angsthase, Weichei, Feigling, [[Federant]], [[Traumined]], [[Bschisserl]], [[Seicherl]]"}]'::jsonb, 'Heast, Augschissana, bist deppad?'),
