  ('luudln', 'luudln', '', '', '', 'Grundwortschatz Wienerisch', 'ludeln', '[{"kategorie": "wörtlich", "text": "\"ludeln\" (vom mittelhochdeutschen \"lūdelen\"=\"lullen\")"}, {"kategorie": "fig.", "text": "\"saugen\", \"lutschen\", [[zuzeln]], (scherzhaft auch) an einer Pfeife/Zigarre, etc. ziehen, nuckeln"}, {"kategorie": "eine Melodie, etc.", "text": "leiern, dudeln, lullen, mit sanfter Stimme singen, einlullen"}, {"kategorie": "scherzhaft für", "text": "Wasser lassen, das kleine Geschäft verrichten, lullen, [[brunzen]], [[schiffen]], [[wiescheln]], [[bridschln]]"}]'::jsonb, 'Des Bauxal hod am Daam gluudld, bis eigschloofn is!'),
